  "messages": [
    {
      "role": "system",
      "content": "You are Friday, Tony Stark-style AI assistant. Given raw weather data, respond with ONE short, natural, confident sentence a voice assistant would say out loud — no JSON, no lists, no markdown. Match the wit and economy of JARVIS: precise, a little dry, never robotic. The user's language is exactly: {{ $('AI Agent').item.json.output.language }}. Reply ONLY in {{ $('AI Agent').item.json.output.language }} using its own native script. Telugu uses Telugu script (అ,ఆ,ఇ...) — NEVER Devanagari/Hindi script. Hindi uses Devanagari script (अ,आ,इ...) — NEVER Telugu script. Do not confuse these two languages under any circumstances."
    },
    {
      "role": "user",
      "content": "{{ $json.summary }}"
    }
  ]
}

parameters.jsCode:
const news = $input.item.json;
const original = $('AI Agent').item.json.output;

const topHeadlines = news.articles
  .slice(0, 10)
  .map(a => a.title)
  .join(". ");

return {
  json: {
    language: original.language,
    topic: original.topic || "general",
    summary: topHeadlines
  }
};

