parameters.jsCode:
// Get the response from the HTTP Request node (IP geolocation API)
const input = $input.first().json;

// ip-api.com response fields: city, regionName, country, lat, lon, etc.
const city = input.city;
const region = input.regionName;
const country = input.country;
const lat = input.lat;
const lon = input.lon;

if (!city && (!lat || !lon)) {
  throw new Error('Location data missing from HTTP Request response. Check field names.');
}

return [
  {
    json: {
      city: city,
      region: region,
      country: country,
      lat: lat,
      lon: lon,
      // combined string, handy for weather APIs that take a place name
      location: [city, region, country].filter(Boolean).join(', ')
    }
  }
];
